mapper.select:
/* Attd15Mapper.selectTargetUsers */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.NODE_CD , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
SELECT S.SITE_NM AS siteNm , U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm FROM target_user U INNER JOIN TB_SITE S ON S.CMPNY_CD = U.CMPNY_CD AND S.SITE_CD = U.SITE_CD ORDER BY U.USER_CD

/* Attd15Mapper.selectWeeklyScheduledRows */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
SELECT U.USER_CD AS userCd , WP.WORK_YMD AS workYmd , SCH.FST_SCH_STR_TIME AS fstSchStrTime , SCH.FST_SCH_END_TIME AS fstSchEndTime , SCH.FST_SCH_BRK_MIN AS fstSchBrkMin , SCH.SEC_SCH_STR_TIME AS secSchStrTime , SCH.SEC_SCH_END_TIME AS secSchEndTime , SCH.SEC_SCH_BRK_MIN AS secSchBrkMin /* HB-07(D3, Q4 확정 2026-08-07): 그날 확정 연차 면제분. 주간 "등록된 스케줄 기준" 소정 합계에서 이 값을 뺀다 — 반차일은 D-H, 종일 연차일은 0. ★ "반차만 제외"는 종일(540분) > 반차(270분) 역전을 만들어 채택 불가. TB_USER_WORK_PLAN 은 연차일에도 SCH_CD 를 유지하므로(prafta-com-008-E-2) 조인 없이는 종일 연차일 소정이 전량 계상된다 — 연차 사용자에게 가짜 "초과" 경보가 뜨던 원인. 부분연차 면제분(분할차감 행은 첫 행에만 총량 — 불변식) 합계와, 종일 연차 존재 여부를 따로 내린다(종일 면제분 = D 이고 D 는 서비스가 ScheduleWorkMinutesUtils 로 계산). */ , IFNULL(( SELECT SUM(L.LEAVE_MINUTES) FROM TB_USER_LEAVE_USE L WHERE L.CMPNY_CD = WP.CMPNY_CD AND L.USER_CD = WP.USER_CD AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.START_DATE = WP.WORK_YMD AND L.USE_UNIT_TYPE <> '00' ), 0) AS leaveExemptMinutes , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE LF WHERE LF.CMPNY_CD = WP.CMPNY_CD AND LF.USER_CD = WP.USER_CD AND LF.LEAVE_STATUS = 'CONFIRMED' AND LF.DEL_YN = 'N' AND LF.USE_UNIT_TYPE = '00' AND LF.START_DATE <= WP.WORK_YMD AND LF.END_DATE >= WP.WORK_YMD ) THEN 'Y' ELSE 'N' END AS fullDayLeaveYn /* PRAFTA-FIXEDOT-2: 고정연장(전방·후방) — 주간 잠정치(예정 근로) 편입용. record(ScheduledRowResult) 끝 4필드와 동일 순서로 SELECT 끝에 둔다(위치 기반 매핑). */ , SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime FROM target_user U INNER JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = U.CMPNY_CD AND WP.SITE_CD = U.SITE_CD AND WP.USER_CD = U.USER_CD AND WP.WORK_YMD BETWEEN #{weekStartYmd} AND #{weekEndYmd}
/* 근무계획코드가 스케줄코드(SCH_CD)인 근무일만 남긴다 — INNER JOIN 이 자연 필터(LEAVE_CD 는 아래 서브쿼리와 매칭되지 않아 제외됨. Attd11Mapper.selectAbsentDayCount 의 "모수" EXISTS 서브쿼리와 동일한 필터 의도를 INNER JOIN 매칭 실패로 달성). 근무일(WP.WORK_YMD) 기준 유효 스케줄(effective-dating): TB_SCH_MGMT(현재본) + TB_SCH_MGMT_HIST(전 버전) UNION 후 APPLY_DATE <= WORK_YMD 인 가장 최근 버전(없으면 MIN 폴백). Attd11Mapper 동일 서브쿼리. */ INNER JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M
UNION ALL
SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
ORDER BY U.USER_CD, WP.WORK_YMD

/* Attd15Mapper.selectWeeklyActualRows */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
SELECT U.USER_CD AS userCd , A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_BRK_MIN ELSE SCH.FST_SCH_BRK_MIN END AS planBreakMin , A.CHECK_IN_DATE AS actInDate , A.CHECK_IN_TIME AS actInTime , A.CHECK_OUT_DATE AS actOutDate , A.CHECK_OUT_TIME AS actOutTime /* PRAFTA-FIXEDOT-3(J2): 그날 스케줄 원시 시각 + 고정연장(전방·후방) — 서비스가 "고정연장 실적(실근태 ∩ 고정연장, FixedOtMinutesUtils)"을 파생 계산해 연장 축에 분류한다. 실근무 총량 합산식은 불변(이중 계상 없음 — 계상분은 raw 실근태에 이미 포함). ⚠️ record(ActualRowResult) 끝 8필드와 동일 순서로 SELECT 끝에 둔다(위치 기반 매핑). */ , SCH.FST_SCH_STR_TIME AS fstSchStrTime , SCH.FST_SCH_END_TIME AS fstSchEndTime , SCH.SEC_SCH_STR_TIME AS secSchStrTime , SCH.SEC_SCH_END_TIME AS secSchEndTime , SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime
FROM target_user U INNER JOIN TB_USER_ATTD_MGMT A ON A.CMPNY_CD = U.CMPNY_CD AND A.SITE_CD = U.SITE_CD AND A.USER_CD = U.USER_CD AND A.WORK_SEQ IN (1, 2) AND A.DEL_YN = 'N' AND A.WORK_YMD BETWEEN #{weekStartYmd} AND #{weekEndYmd}
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
/* 근무일(A.WORK_YMD) 기준 유효 스케줄(effective-dating). Attd11Mapper 동일 서브쿼리 복제 (실제 근무 휴게 공제는 스케줄 정의 휴게분을 사용 — Attd11 workMinutes 계산과 동일 기준). */ LEFT JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M
UNION ALL
SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
ORDER BY U.USER_CD, A.WORK_YMD, A.WORK_SEQ

/* Attd15Mapper.selectWeeklyOvertimeSummary */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND (U.EMPLOYMENT_TYPE IS NULL OR U.EMPLOYMENT_TYPE <> 'DAILY')
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
SELECT O.USER_CD AS userCd , IFNULL(SUM(O.WORK_MINUTES), 0) AS otMinutes FROM TB_USER_OVERTIME_MGMT O INNER JOIN target_user U ON O.CMPNY_CD = U.CMPNY_CD AND O.SITE_CD = U.SITE_CD AND O.USER_CD = U.USER_CD WHERE O.CMPNY_CD = #{gvCmpnyCd} AND O.SITE_CD = #{siteCd} AND O.WORK_YMD BETWEEN #{weekStartYmd} AND #{weekEndYmd} AND O.DEL_YN = 'N' AND O.OT_STATUS = 'COMPLETED' GROUP BY O.USER_CD

/* Attd15Mapper.selectWeeklyTimeLeaveWindows */
    SELECT DISTINCT
          L.USER_CD     AS userCd
        , L.START_DATE  AS workYmd
        , L.START_TIME  AS startTime
        , L.END_TIME    AS endTime
    FROM TB_USER_LEAVE_USE L
    WHERE L.CMPNY_CD      = #{gvCmpnyCd}
      AND L.SITE_CD       = #{siteCd}
      AND L.START_DATE  >=  #{weekStartYmd}
      AND L.START_DATE  <=  #{weekEndYmd}
      AND L.USE_UNIT_TYPE IN ('01', '02', '03', '04')
      AND L.LEAVE_STATUS  = 'CONFIRMED'
      AND L.DEL_YN        = 'N'
      AND L.START_TIME IS NOT NULL
      AND L.END_TIME   IS NOT NULL
